#include <iostream>
#include <string>
#include <utility>

class GradeBook {
public:
    // Explicit constructor using member initializer list
    explicit GradeBook(std::string name)
        : courseName(std::move(name))
    {
        // Body is intentionally empty
    }

    void setCourseName(std::string name) {
        courseName = std::move(name);
    }

    [[nodiscard]] std::string getCourseName() const {
        return courseName;
    }

    void displayMessage() const {
        std::cout << "Welcome to the grade book for\n" << getCourseName() << "!\n";
    }

private:
    std::string courseName;
};

int main() {
    GradeBook gradeBook1("CS101 Introduction to C++ Programming");
    GradeBook gradeBook2("CS102 Data Structures in C++");

    std::cout << "gradeBook1 created for course: " << gradeBook1.getCourseName()
              << "\ngradeBook2 created for course: " << gradeBook2.getCourseName()
              << std::endl;
    return 0;
}

